#!/bin/bash
# GENERATED by tools/host_leaf_suite.py gen-script leaf_a1 - edit the @leaf
# markers in leaf_a1_harness.c, not this file.
# Compiles the unchanged decomp units below, links them with the leaf harness
# and runs the per-function checks under QEMU.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
DECOMP="${DECOMP:-$(cd "$HERE/../.." && pwd)}"
T="${TOOLCHAIN:-$DECOMP/.toolchain}"
OUT="${OUT:-$HERE/build-leaf-a1}"
QEMU="${QEMU:-$HOME/.local/share/qemu-user/extracted/usr/bin/qemu-mipsel}"
GCC="$T/gcc-2.7.2-cdk/gcc"
MASPSX="$(echo "$T"/maspsx-*/maspsx.py)"
mkdir -p "$OUT"
export PATH="$T/mipsel-binutils/root/usr/bin:$PATH"
export LD_LIBRARY_PATH="$T/mipsel-binutils/root/usr/lib/x86_64-linux-gnu${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"

compile() {
    local src="$1" obj="$2"; shift 2
    "$GCC" -B"$T/gcc-2.7.2-cdk/" -I"$DECOMP/include" "$@" -O1 -G0 -S "$src" -o "$OUT/tmp.s"
    python3 "$MASPSX" "$OUT/tmp.s" | python3 "$HERE/fix_align.py" > "$OUT/tmp.mas.s"
    mipsel-linux-gnu-as -o "$obj" "$OUT/tmp.mas.s"
}

objects=()
for unit in 80015AF4 80049EF8 8001A750 8001A6F8 800187C8 800886C8 8003B65C 8001BC44 8001BC64 8001BCD0 8001BCA4 8001BD2C 8001C27C 8001C470 80018460 8001E304 8001E4C0 80095830 80091B1C 80091C90 80028BA0 8008D5D0 80095FE8 800195A4 800195D0 8003BEF0 80021800 8002B1AC 800489C8 8007D39C 8008C858 8007AA9C 8007F688 8008E720 8001C3F8 8008AE70 8008AE7C 8008B4EC 8008B71C 8008B73C 8008B750 8008B770 8008B790 8008B7B0 8008C06C 8004DA58 80092488 8009249C 800924B0 800924C4 800924D8 800924EC 80092514 80092528 8009253C 80092550 80092564 80092578 8009258C 800925A0 800925D4 800925F4 80092410 80092438 80092340 800923D4 800923F8 80092398 80092230 8009226C 80093F58 800940A8 800940C4 80093A4C 80093A74 800607B8; do
    compile "$DECOMP/src/game/$unit.c" "$OUT/$unit.o"
    objects+=("$OUT/$unit.o")
done
python3 "$HERE/leaf_vectors.py" > "$OUT/leaf_vectors.h"
compile "$HERE/leaf_a1_harness.c" "$OUT/leaf_a1_harness.o" -I"$OUT" -I"$HERE"
mipsel-linux-gnu-as -o "$OUT/crt0.o" "$HERE/crt0.s" 2>/dev/null
mipsel-linux-gnu-ld -static -e __start -o "$OUT/leaf_a1" \
    "$OUT/crt0.o" "$OUT/leaf_a1_harness.o" "${objects[@]}"
"$QEMU" "$OUT/leaf_a1"
